### Python

```python
# -*- coding: utf-8 -*-
import sys

def max_of_min_for_all_windows(a):
    n = len(a)
    pre = [-1] * n  # 左侧第一个严格更小的位置
    nxt = [n] * n   # 右侧第一个小于等于的位置

    # 计算 pre：维护单调递增栈，保证栈顶元素 < 当前值
    st = []
    for i in range(n):
        # 弹出 >= a[i]，以确保得到严格更小
        while st and a[st[-1]] >= a[i]:
            st.pop()
        pre[i] = st[-1] if st else -1
        st.append(i)

    # 计算 nxt：从右往左，维护单调递增栈，得到 <= a[i]
    st.clear()
    for i in range(n - 1, -1, -1):
        # 弹出 > a[i]，使得栈顶 <= a[i]
        while st and a[st[-1]] > a[i]:
            st.pop()
        nxt[i] = st[-1] if st else n
        st.append(i)

    ans = [0] * (n + 1)  # ans[len] 表示长度为 len 的答案
    for i in range(n):
        length = nxt[i] - pre[i] - 1
        if a[i] > ans[length]:
            ans[length] = a[i]

    # 后缀最大，填补尚未被直接更新的位置
    for x in range(n - 1, 0, -1):
        if ans[x + 1] > ans[x]:
            ans[x] = ans[x + 1]

    return ans[1:]  # 去掉 0 位置

def main():
    data = list(map(int, sys.stdin.read().strip().split()))
    if not data:
        return
    n = data[0]
    a = data[1:1 + n]
    res = max_of_min_for_all_windows(a)
    print(" ".join(map(str, res)))

if __name__ == "__main__":
    main()
```

