```java
// 注意：ACM 风格，主类名为 Main
import java.io.*;
import java.util.*;

public class Main {
    // 计算所有窗口长度的“最大最小值”
    static int[] maxOfMinForAllWindows(int[] a) {
        int n = a.length;
        int[] pre = new int[n];
        int[] nxt = new int[n];
        Arrays.fill(pre, -1);
        Arrays.fill(nxt, n);

        // pre：左侧第一个严格更小的位置
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!st.isEmpty() && a[st.peek()] >= a[i]) st.pop();
            pre[i] = st.isEmpty() ? -1 : st.peek();
            st.push(i);
        }

        // nxt：右侧第一个小于等于的位置
        st.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.isEmpty() && a[st.peek()] > a[i]) st.pop();
            nxt[i] = st.isEmpty() ? n : st.peek();
            st.push(i);
        }

        int[] ans = new int[n + 1];
        for (int i = 0; i < n; i++) {
            int len = nxt[i] - pre[i] - 1;
            if (a[i] > ans[len]) ans[len] = a[i];
        }
        // 后缀最大
        for (int x = n - 1; x >= 1; x--) {
            if (ans[x + 1] > ans[x]) ans[x] = ans[x + 1];
        }
        return Arrays.copyOfRange(ans, 1, n + 1);
    }

    // 适配数据规模的简易快读
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;
        FastScanner(InputStream is) { in = is; }
        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
        int nextInt() throws IOException {
            int c, sgn = 1, x = 0;
            do { c = read(); } while (c <= ' ');
            if (c == '-') { sgn = -1; c = read(); }
            while (c > ' ') { x = x * 10 + (c - '0'); c = read(); }
            return x * sgn;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = fs.nextInt();

        int[] res = maxOfMinForAllWindows(a);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) {
            if (i > 0) sb.append(' ');
            sb.append(res[i]);
        }
        System.out.println(sb.toString());
    }
}
