// ACM 风格，主函数中读写，核心逻辑写在外部函数
#include <bits/stdc++.h>
using namespace std;

// 计算所有窗口长度的“最大最小值”
vector<long long> maxOfMinForAllWindows(const vector<long long>& a) {
    int n = (int)a.size();
    vector<int> pre(n, -1), nxt(n, n);
    vector<int> st;

    // pre：左侧第一个严格更小的位置
    st.clear();
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && a[st.back()] >= a[i]) st.pop_back();
        pre[i] = st.empty() ? -1 : st.back();
        st.push_back(i);
    }

    // nxt：右侧第一个小于等于的位置
    st.clear();
    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && a[st.back()] > a[i]) st.pop_back();
        nxt[i] = st.empty() ? n : st.back();
        st.push_back(i);
    }

    vector<long long> ans(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        int len = nxt[i] - pre[i] - 1;
        ans[len] = max(ans[len], a[i]);
    }
    // 后缀最大
    for (int x = n - 1; x >= 1; --x) {
        ans[x] = max(ans[x], ans[x + 1]);
    }
    ans.erase(ans.begin()); // 去掉 0 位置
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    vector<long long> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    vector<long long> res = maxOfMinForAllWindows(a);
    for (int i = 0; i < (int)res.size(); ++i) {
        if (i) cout << ' ';
        cout << res[i];
    }
    cout << "\n";
    return 0;
}
